import{_ as t,o as e,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Управление файлами Bot","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/files.md","filePath":"ru/guides/files.md","lastUpdated":1792323081000}'),l={name:"ru/guides/files.md"};function n(s,o,i,d,h,g){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="управление-фаилами-bot" tabindex="-1">Управление файлами Bot <a class="header-anchor" href="#управление-фаилами-bot" aria-label="Permalink to &quot;Управление файлами Bot&quot;">​</a></h1><p>У каждого Bot в Memoh есть собственная файловая система рабочего пространства. В серверных развёртываниях она обычно живёт внутри контейнерного рабочего пространства Bot; в доверенном настольном/локальном режиме это может быть локальный каталог рабочего пространства. Управлять этой файловой системой можно напрямую с вкладки <strong>Files</strong> на странице деталей Bot.</p><hr><h2 id="операции" tabindex="-1">Операции <a class="header-anchor" href="#операции" aria-label="Permalink to &quot;Операции&quot;">​</a></h2><p>Компонент <strong>FileManager</strong> даёт привычный опыт работы с файлами: панель инструментов, дерево каталогов и встроенный редактор.</p><h3 id="просмотр-и-навигация" tabindex="-1">Просмотр и навигация <a class="header-anchor" href="#просмотр-и-навигация" aria-label="Permalink to &quot;Просмотр и навигация&quot;">​</a></h3><ul><li><strong>Хлебные крошки</strong>: быстрое перемещение между родительскими каталогами.</li><li><strong>Refresh</strong>: перезагрузка списка файлов, чтобы увидеть последние изменения (например, файлы, созданные Bot).</li><li><strong>New Folder</strong>: создание каталога по текущему пути.</li></ul><h3 id="управление-фаилами" tabindex="-1">Управление файлами <a class="header-anchor" href="#управление-фаилами" aria-label="Permalink to &quot;Управление файлами&quot;">​</a></h3><ul><li><strong>Upload</strong>: выберите файлы на своём компьютере, чтобы перенести их в рабочее пространство Bot.</li><li><strong>Rename</strong>: щёлкните по файлу или папке и используйте действие переименования, чтобы изменить имя.</li><li><strong>Delete</strong>: удаление файлов и папок (для каталогов — с рекурсией).</li><li><strong>Download</strong>: заберите файл из рабочего пространства Bot обратно на свою машину.</li></ul><hr><h2 id="просмотр-и-редактирование" tabindex="-1">Просмотр и редактирование <a class="header-anchor" href="#просмотр-и-редактирование" aria-label="Permalink to &quot;Просмотр и редактирование&quot;">​</a></h2><p>Встроенный <strong>FileViewer</strong> позволяет работать с файлами Bot, не покидая приложение.</p><h3 id="текстовые-фаилы" tabindex="-1">Текстовые файлы <a class="header-anchor" href="#текстовые-фаилы" aria-label="Permalink to &quot;Текстовые файлы&quot;">​</a></h3><ul><li><strong>Чтение/правка</strong>: щёлкните по текстовому файлу (например <code>.md</code>, <code>.js</code>, <code>.py</code>, <code>.toml</code>), чтобы открыть его во встроенном редакторе <strong>Monaco Editor</strong>.</li><li><strong>Подсветка синтаксиса</strong>: поддерживаются распространённые языки программирования и форматы конфигураций.</li><li><strong>Сохранение</strong>: измените содержимое файла и нажмите <strong>Save</strong>, чтобы применить изменения к файловой системе рабочего пространства Bot.</li></ul><h3 id="изображения" tabindex="-1">Изображения <a class="header-anchor" href="#изображения" aria-label="Permalink to &quot;Изображения&quot;">​</a></h3><ul><li><strong>Предпросмотр</strong>: щёлкните по файлу изображения (например <code>.png</code>, <code>.jpg</code>, <code>.webp</code>), чтобы увидеть его прямо в файловом менеджере.</li></ul><hr><h2 id="как-bot-работает-с-фаилами" tabindex="-1">Как Bot работает с файлами <a class="header-anchor" href="#как-bot-работает-с-фаилами" aria-label="Permalink to &quot;Как Bot работает с файлами&quot;">​</a></h2><p>Помните, что Bot и сам может выполнять эти операции:</p><ul><li>Использовать свои <strong>навыки</strong> или <strong>инструменты MCP</strong>, чтобы читать, записывать и управлять собственными файлами.</li><li>Вкладка <strong>Files</strong> — ваш портал для наблюдения за рабочим пространством Bot и ручного вмешательства в него.</li></ul>',20)])])}const p=t(l,[["render",n]]);export{u as __pageData,p as default};
